Unit Test Code:
#include "unity.h"
#include "buffer.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_append_n_resize_successful(void) {
    // Setup: create a buffer with small initial data and size
    // Initial buffer: "foo", size 4 (just enough for "foo\0")
    buffer_t *buf = helper_make_buffer_with_size(4);
    TEST_ASSERT_NOT_NULL(buf);
    strcpy(buf->data, "foo");

    // Prepare string to append
    const char *to_append = "barbaz";
    size_t append_len = 6; // append "barbaz"

    // This will require resizing: strlen("foo") = 3, needed = 3+6=9 > 4
    int ret = buffer_append_n(buf, to_append, append_len);

    // Assertions
    TEST_ASSERT_EQUAL(0, ret);
    // After append, buffer should contain "foobarbaz"
    helper_assert_buffer_data_equals(buf, "foobarbaz");
    helper_assert_buffer_length(buf, 9);
    // Buffer size should be at least 9 (implementation may round up)
    TEST_ASSERT_TRUE(buffer_size(buf) >= 9);

    // Cleanup
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_append_n_resize_successful);
    return UNITY_END();
}

